<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{--navy:#071E45;--dark:#020817;--gold:#D79A21;--gold2:#F2B233;--ink:#101828;--muted:#667085;--line:#E6ECF4;--green:#16794B;--off:#F8FAFC;--font:'Plus Jakarta Sans',system-ui,sans-serif}
body{font-family:var(--font);color:var(--ink);background:#fff;line-height:1.6;overflow-x:hidden}
a{text-decoration:none;color:inherit}.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;border-radius:10px;padding:13px 22px;font-size:14px;font-weight:900;border:1px solid transparent;transition:.2s}.btn:hover{transform:translateY(-2px)}.btn-gold{background:linear-gradient(180deg,var(--gold2),var(--gold));color:#071E45;box-shadow:0 16px 40px rgba(215,154,33,.24)}.btn-outline{border-color:rgba(255,255,255,.42);color:#fff;background:rgba(255,255,255,.06)}.btn-navy{background:var(--navy);color:#fff}
.topbar{position:fixed;top:0;left:0;right:0;z-index:50;height:76px;padding:0 clamp(18px,4vw,64px);display:flex;align-items:center;justify-content:space-between;gap:24px;background:rgba(2,8,23,.86);backdrop-filter:blur(18px);border-bottom:1px solid rgba(255,255,255,.08)}
.brand{display:flex;align-items:center;gap:11px;color:#fff}.brand img{width:42px;height:42px;border-radius:11px}.brand strong{font-size:22px;font-weight:900;letter-spacing:-.05em}.brand strong span{color:var(--gold2)}.brand small{display:block;font-size:11px;color:rgba(255,255,255,.76);margin-top:-4px}
.navlinks{display:flex;align-items:center;gap:30px;color:rgba(255,255,255,.86);font-weight:700;font-size:14px}.navlinks a:hover{color:var(--gold2)}.nav-actions{display:flex;gap:10px}.menu{display:none;background:rgba(255,255,255,.1);border:0;color:#fff;border-radius:10px;width:42px;height:42px;font-size:22px}.mobile{display:none;position:fixed;top:76px;left:0;right:0;z-index:49;background:#061632;padding:18px}.mobile.open{display:grid}.mobile a{color:#fff;padding:12px;border-radius:10px}.mobile a:hover{background:rgba(255,255,255,.08)}
.hero{background:#020817;padding-top:76px}.hero-art{position:relative;min-height:calc(100vh - 76px);background:#020817;overflow:hidden}.hero-art img{width:100%;height:100%;min-height:calc(100vh - 76px);display:block;object-fit:cover;object-position:center top}.hero-actions-overlay{position:absolute;left:clamp(24px,4vw,64px);bottom:clamp(28px,5vw,78px);display:flex;gap:14px;flex-wrap:wrap;z-index:2}.hero-actions-overlay .btn-outline{background:rgba(2,8,23,.28);backdrop-filter:blur(10px)}
.content-section{padding:90px clamp(22px,4vw,64px)}.section-inner{max-width:1180px;margin:0 auto}.center{text-align:center}.eyebrow{font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:var(--gold);font-weight:900;margin-bottom:12px}.title{font-size:clamp(30px,4vw,48px);letter-spacing:-.045em;line-height:1.1;color:var(--navy)}.sub{color:var(--muted);font-size:17px;max-width:720px;margin:16px auto 0}
.module-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin-top:42px}.module{background:#fff;border:1px solid var(--line);border-radius:18px;padding:24px;box-shadow:0 14px 38px rgba(16,24,40,.07)}.module-icon{width:44px;height:44px;border-radius:13px;background:linear-gradient(180deg,var(--gold2),var(--gold));display:grid;place-items:center;color:#fff;font-size:20px;margin-bottom:14px}.module h3{font-size:16px;color:var(--navy);margin-bottom:8px}.module p{font-size:13px;color:var(--muted)}
.pricing{background:var(--off)}.plans{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin-top:42px}.plan{background:#fff;border:1px solid var(--line);border-radius:20px;padding:30px;box-shadow:0 16px 44px rgba(16,24,40,.08)}.plan-top{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.plan h3{font-size:24px;color:var(--navy)}.tag{background:var(--green);color:#fff;border-radius:9px;padding:10px 14px;font-size:12px;font-weight:900;white-space:nowrap}.tag.gold{background:linear-gradient(180deg,var(--gold2),var(--gold));color:#071E45}.price{font-size:46px;font-weight:900;color:var(--navy);letter-spacing:-.045em;margin:22px 0 4px}.price small{font-size:14px;color:var(--muted)}.plan p{color:var(--muted);font-size:14px}
.portals{background:#071E45;color:#fff}.portals .title{color:#fff}.portals .sub{color:rgba(255,255,255,.68)}.portal-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin-top:42px}.portal{display:block;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.12);border-radius:18px;padding:24px;transition:.2s}.portal:hover{background:rgba(255,255,255,.1);border-color:rgba(215,154,33,.42);transform:translateY(-2px)}.portal h3{font-size:17px;margin:12px 0 8px}.portal p{font-size:13px;color:rgba(255,255,255,.66)}
.download{background:#fff}.download-card{max-width:920px;margin:0 auto;background:linear-gradient(135deg,#071E45,#020817);border-radius:28px;color:#fff;padding:46px;display:flex;align-items:center;justify-content:space-between;gap:24px;box-shadow:0 24px 70px rgba(7,30,69,.24)}.download-card p{color:rgba(255,255,255,.72);margin-top:8px}
footer{background:#020817;color:rgba(255,255,255,.66);padding:64px clamp(22px,4vw,64px) 32px}.footer-grid{max-width:1180px;margin:0 auto 44px;display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:40px}.footer-brand{display:flex;align-items:center;gap:10px;margin-bottom:12px}.footer-brand img{width:34px;height:34px;border-radius:8px}.footer-brand span{font-size:19px;font-weight:900;color:#fff}.footer-brand span b{color:var(--gold2)}.footer-about p{font-size:13px;max-width:340px}.contact-list{display:grid;gap:10px;margin-top:18px}.contact-row{display:flex;align-items:center;gap:10px}.contact-row svg{width:16px;height:16px;color:var(--gold);flex:0 0 auto}.contact-row a{font-size:13px;color:rgba(255,255,255,.76);font-weight:700}.contact-row a:hover,.foot-col a:hover{color:var(--gold2)}.foot-col h4{font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:#fff;margin-bottom:14px}.foot-col a{display:block;font-size:13px;color:rgba(255,255,255,.56);padding:4px 0}.footer-bottom{max-width:1180px;margin:0 auto;border-top:1px solid rgba(255,255,255,.08);padding-top:24px;display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap}.footer-bottom p,.footer-bottom a{font-size:12px}.footer-links{display:flex;gap:20px}
@media(max-width:1040px){.navlinks,.nav-actions{display:none}.menu{display:block}.hero-art img{height:auto;min-height:0}.hero-actions-overlay{position:static;background:#020817;padding:22px clamp(18px,4vw,40px);justify-content:center}.module-grid,.portal-grid{grid-template-columns:repeat(2,1fr)}.footer-grid{grid-template-columns:1fr 1fr}.download-card{align-items:flex-start;flex-direction:column}}
@media(max-width:640px){.topbar{height:68px}.mobile{top:68px}.hero{padding-top:68px}.brand img{width:36px;height:36px}.brand strong{font-size:19px}.module-grid,.plans,.portal-grid,.footer-grid{grid-template-columns:1fr}.content-section{padding:64px 20px}.download-card{padding:30px}.hero-actions-overlay .btn{width:100%}.footer-bottom{flex-direction:column}}
</style>
